#include <iostream>
using namespace std;

using ll = long long;

const ll MOD = 1000000007;

ll modPow(ll base, int exp) {
    ll result = 1;
    base %= MOD;

    while (exp > 0) {
        if (exp & 1)
            result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    ll ans = modPow(n - k, n - k);
    ll connected = (k <= 1) ? 1 : modPow(k, k - 2);

    cout << ans * connected % MOD << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <cstring>

using namespace std;

using ll = long long;

const int MOD = 1000000007;

int n, k;
vector<int> sec;
bool mark[20];
vector<int> adj[20];

int dfs(int v) {
    if (mark[v]) return 0;
    mark[v] = true;

    int ret = 1;
    for (int u : adj[v])
        ret += dfs(u);

    return ret;
}

void gen(int rem, ll& cnt) {
    if (rem == 0) {
        memset(mark, 0, sizeof(mark));
        for (int i = 0; i < k; ++i)
            adj[i].clear();

        for (int i = 0; i < k; ++i)
            adj[sec[i]].push_back(i);

        if (dfs(0) == k)
            cnt = (cnt + 1) % MOD;

        return;
    }

    for (int i = 0; i < k; ++i) {
        sec.push_back(i);
        gen(rem - 1, cnt);
        sec.pop_back();
    }
}

ll get() {
    ll cnt = 0;
    gen(k, cnt);
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;

    ll ans = 1;
    for (int i = 0; i < n - k; ++i)
        ans = ans * (n - k) % MOD;

    ans = ans * get() % MOD;
    cout << ans << '\n';

    return 0;
}

