#include <iostream>
using namespace std;

using ll = long long;

const ll MOD = 1000000007LL;

ll modPow(ll base, ll exp) {
    base %= MOD;
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

ll get(int k) {
    ll answer = 0;
    ll cycleWays = 1;

    for (int cycleLength = 1; cycleLength <= k; ++cycleLength) {
        if (cycleLength > 1) {
            cycleWays = cycleWays * (k - cycleLength + 1) % MOD;
        }

        ll forestWays;
        int remaining = k - cycleLength;

        if (remaining == 0) {
            forestWays = 1;
        } else {
            forestWays = cycleLength * modPow(k, remaining - 1) % MOD;
        }

        answer = (answer + cycleWays * forestWays) % MOD;
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    ll answer = modPow(n - k, n - k);
    answer = answer * get(k) % MOD;

    cout << answer << '\n';
    return 0;
}

